AssistantMessageToolRequest(name='create', tool_call_id='function-call-fee24b3f-a4bc-4eb4-8fbe-aba327575e46', arguments={'file_text': 'document.addEventListener('DOMContentLoaded', () => {
  const form = document.getElementById('preferences-form');
  const statusMessage = document.getElementById('status-message');
  const errorContainer = document.getElementById('group-error');
  const fieldset = document.getElementById('notification-fieldset');
  const radios = form.querySelectorAll('input[name="notification_preference"]');

  form.addEventListener('submit', (e) => {
    e.preventDefault();

    // Check if a radio is selected
    const selected = form.querySelector('input[name="notification_preference"]:checked');

    if (!selected) {
      // Show error programmatically and visually
      errorContainer.classList.add('visible');
      errorContainer.textContent = "Error: Please choose how you prefer to receive notifications.";

      radios.forEach(radio => radio.setAttribute('aria-invalid', 'true'));

      // Update aria-describedby on fieldset to include error text
      const currentDesc = fieldset.getAttribute('aria-describedby') || '';
      if (!currentDesc.includes('group-error')) {
        fieldset.setAttribute('aria-describedby', `${currentDesc} group-error`.trim());
      }

      // Focus the first radio button so the user is right where they need to make a correction
      radios[0].focus();
    } else {
      // Clear errors
      errorContainer.classList.remove('visible');
      radios.forEach(radio => radio.removeAttribute('aria-invalid'));

      let currentDesc = fieldset.getAttribute('aria-describedby') || '';
      currentDesc = currentDesc.replace('group-error', '').trim();
      if (currentDesc) {
        fieldset.setAttribute('aria-describedby', currentDesc);
      } else {
        fieldset.removeAttribute('aria-describedby');
      }

      // Display success message
      const labelText = document.querySelector(`label[for="${selected.id}"]`).textContent;
      statusMessage.textContent = `Preferences saved! We will send you ${labelText}.`;
      statusMessage.hidden = false;
    }
  });

  // Clear errors dynamically when the user makes a selection
  radios.forEach(radio => {
    radio.addEventListener('change', () => {
      errorContainer.classList.remove('visible');
      radios.forEach(r => r.removeAttribute('aria-invalid'));

      let currentDesc = fieldset.getAttribute('aria-describedby') || '';
      currentDesc = currentDesc.replace('group-error', '').trim();
      if (currentDesc) {
        fieldset.setAttribute('aria-describedby', currentDesc);
      } else {
        fieldset.removeAttribute('aria-describedby');
      }

      statusMessage.hidden = true;
    });
  });
